    this.boot();
    var pid = parseInt(parserId, 10) || 0;
    playId = String(playId);
    if (playId.indexOf('http') === 0) {
        if (/\.(m3u8|mp4|flv|mkv|ts)(\?|$)/i.test(playId)) return playId;
        return this.parseAny(pid, playId);
    }
    var payload = gCat(gFv(1, pid), gFb(2, utf8(playId)));
    var plain = this.req(69, payload);
    var got = ustr(gOne(gOne(plain, 4, [], 2), 2, [], 2));
    if (!got) return '';
    if (/\.(m3u8|mp4|flv|mkv|ts)(\?|$)/i.test(got)) return got;
    if (got.indexOf('http') === 0) return this.parseAny(pid, got);
    return got;
};

