function gEps(src, parserId, reverse) {
    var out = [], cur, start, end, i, ep, n;
    cur = parseInt(gSafe(getMyVar('gulu_ep', '0')), 10) || 0;
    n = src.eps.length;
    start = cur * G_EPPAGE;
    end = Math.min(n, start + G_EPPAGE);
    if (reverse) {
        for (i = end - 1; i >= start; i--) out.push(gEpItem(src.eps[i], parserId));
    } else {
